// Exact two-mask surgery on the current THM-4283 residual signature ideal
// generated by the endpoint-637 row (520,637).
//
// The inherited 421-mask joint deck is a body cover.  Its inactive signature
// at (520,637) is exactly {275,345}.  This audit deletes those two masks,
// enumerates every newly exposed labelled nine-body, intersects the complete
// rank-eight activity universes over the whole current-residual signature
// ideal I(p) subset {275,345}, solves the resulting response quotient exactly,
// and exhaustively rescans the rebuilt deck on all C(30,9) bodies.  Direct
// signed-margin evaluation separately checks strict activity of every rebuilt
// mask at every certified row.

#define RESPONSE_PATTERN_ATLAS_LIBRARY_ONLY
#include "04-computation/lrc14_joint421_global_common_carrier_thm4281/response_pattern_atlas.cpp"
#undef RESPONSE_PATTERN_ATLAS_LIBRARY_ONLY

