namespace {

constexpr std::size_t kSignatureRows = 24223;
constexpr u64 kSignaturePairFnv = UINT64_C(0x80ec0687d8c7dba7);
constexpr u64 kSignatureContentFnv = UINT64_C(0x3652b5590b330704);
constexpr std::size_t kCurrentResidualRows = 22682;
constexpr u64 kCurrentResidualFnv = UINT64_C(0xf7563445f15efebf);
constexpr std::size_t kJointRows = 421;
constexpr u64 kJointFnv = UINT64_C(0x20d63dd42fe8150e);
constexpr std::size_t kBodyRows = 14307150;

constexpr std::array<std::size_t, 2> kDeletedIndices{275, 345};
constexpr std::array<u32, 2> kDeletedMasks{
    UINT32_C(0x1aa28002), UINT32_C(0x18868880)};
constexpr std::array<u32, 2> kWitnessMasks{
    UINT32_C(0x02229124), UINT32_C(0x1c030206)};
constexpr u64 kWitnessFnv = UINT64_C(0xd3e3e2e829293a5d);

constexpr std::size_t kFibreRows = 33;
constexpr u64 kFibreFnv = UINT64_C(0xf11425c1e1b17094);
constexpr std::size_t kCommonActiveCount = 2027392;
constexpr u64 kCommonActiveFnv = UINT64_C(0x43a535bbda51fab8);
constexpr u64 kCommonResponseFnv = UINT64_C(0x8eccb862de56eed2);
constexpr u64 kClassFnv = UINT64_C(0xb2aa1781ed13dc41);
constexpr u64 kRebuiltDeckFnv = UINT64_C(0x9781de64dff60cee);
constexpr u64 kRebuiltBodyChecks = UINT64_C(405170443);
constexpr u64 kRebuiltBodyRowFnv = UINT64_C(0x3aa84f98dae6429e);
constexpr u64 kActivityLedgerFnv = UINT64_C(0x786acec59e9a652b);
constexpr i128 kWeakestMargin =
    static_cast<i128>(UINT64_C(4256473828607280));

constexpr std::array<u32, 6> kExpectedBodies{
    UINT32_C(0x004c50c9), UINT32_C(0x03306409),
    UINT32_C(0x054c6408), UINT32_C(0x204c50c1),
    UINT32_C(0x23505009), UINT32_C(0x245c0281)};
constexpr std::array<unsigned, 6> kExpectedDeletedResponses{1, 2, 1, 1, 2, 1};
constexpr u64 kBodyFnv = UINT64_C(0x5098163ca56aa069);
constexpr u64 kBodyResponseFnv = UINT64_C(0x70e74babe24e44a1);
constexpr u64 kRetainedChecks = UINT64_C(405170433);

struct Pair637 {
    int q = 0;
    int r = 0;

    friend bool operator<(const Pair637& left, const Pair637& right) {
        return std::tie(left.q, left.r) < std::tie(right.q, right.r);
    }
    friend bool operator==(const Pair637&, const Pair637&) = default;
};

struct Signature637 {
    std::array<u64, 7> words{};
    u64 weight = 0;
};

struct LostBody637 {
    u32 body = 0;
    unsigned deleted_response = 0;
};

struct ResponseClass637 {
    u64 count = 0;
    u32 least = 0;
};

struct FrozenClass637 {
    unsigned pattern = 0;
    u64 count = 0;
    u32 least = 0;
};

constexpr std::array<FrozenClass637, 17> kExpectedClasses{{
    {0x00, 1914892, UINT32_C(0x0000229f)},
    {0x01, 19300,   UINT32_C(0x2012a604)},
    {0x02, 15828,   UINT32_C(0x004c1096)},
    {0x03, 71,      UINT32_C(0x24010236)},
    {0x04, 6553,    UINT32_C(0x001091a5)},
    {0x05, 130,     UINT32_C(0x22308124)},
    {0x08, 12571,   UINT32_C(0x0031a608)},
    {0x09, 17296,   UINT32_C(0x00b0a602)},
    {0x0d, 35,      UINT32_C(0x0a128124)},
    {0x10, 15926,   UINT32_C(0x0004aec0)},
    {0x12, 1277,    UINT32_C(0x040d0096)},
    {0x19, 530,     UINT32_C(0x04012236)},
    {0x1b, 9,       UINT32_C(0x1c030206)},
    {0x20, 21082,   UINT32_C(0x0020544e)},
    {0x24, 49,      UINT32_C(0x02229124)},
    {0x28, 1084,    UINT32_C(0x0122240e)},
    {0x29, 759,     UINT32_C(0x02a22c02)},
}};

std::vector<std::string> split637(const std::string& text, char delimiter) {
    std::vector<std::string> fields;
    std::stringstream stream(text);
    std::string field;
    while (std::getline(stream, field, delimiter)) fields.push_back(field);
    return fields;
}

bool signature_subset637(const Signature637& left,
                         const Signature637& right) {
    for (std::size_t word = 0; word < left.words.size(); ++word)
        if ((left.words[word] & ~right.words[word]) != 0) return false;
    return true;
}

bool signature_bit637(const Signature637& signature, std::size_t index) {
    return ((signature.words[index / 64] >> (index % 64)) & 1) != 0;
}

std::vector<std::size_t> signature_indices637(
    const Signature637& signature) {
    std::vector<std::size_t> indices;
    for (std::size_t index = 0; index < kJointRows; ++index)
        if (signature_bit637(signature, index)) indices.push_back(index);
    return indices;
}

std::map<Pair637, Signature637> read_signatures637(
    const std::filesystem::path& path) {
    std::ifstream input(path);
    require(static_cast<bool>(input), "cannot open signature ledger");
    std::string line;
    require(static_cast<bool>(std::getline(input, line)) &&
                line == "q,r,inactive_count,w0,w1,w2,w3,w4,w5,w6",
            "signature header changed");
    std::map<Pair637, Signature637> signatures;
    FnvLocal pair_ledger;
    FnvLocal content_ledger;
    while (std::getline(input, line)) {
        require(!line.empty(), "blank signature row");
        const std::vector<std::string> fields = split637(line, ',');
        require(fields.size() == 10, "malformed signature row");
        std::size_t used_q = 0;
        std::size_t used_r = 0;
        std::size_t used_weight = 0;
        const Pair637 pair{std::stoi(fields[0], &used_q),
                           std::stoi(fields[1], &used_r)};
        Signature637 signature;
        signature.weight = std::stoull(fields[2], &used_weight);
        require(used_q == fields[0].size() && used_r == fields[1].size() &&
                    used_weight == fields[2].size() && pair.q > 0 &&
                    pair.q < pair.r && signature.weight > 0,
                "invalid signature coordinates/weight");
        u64 reconstructed_weight = 0;
        for (std::size_t word = 0; word < signature.words.size(); ++word) {
            std::size_t used = 0;
            signature.words[word] =
                std::stoull(fields[word + 3], &used, 16);
            require(used == fields[word + 3].size(),
                    "invalid signature word");
            reconstructed_weight += std::popcount(signature.words[word]);
        }
        require(reconstructed_weight == signature.weight &&
                    (signature.words[6] >> 37) == 0,
                "signature weight/padding changed");
        require(signatures.emplace(pair, signature).second,
                "duplicate signature pair");
        pair_ledger.add(pair.q);
        pair_ledger.add(pair.r);
        content_ledger.add(pair.q);
        content_ledger.add(pair.r);
        content_ledger.add(signature.weight);
        for (u64 word : signature.words) content_ledger.add(word);
    }
    require(signatures.size() == kSignatureRows &&
                pair_ledger.state == kSignaturePairFnv &&
                content_ledger.state == kSignatureContentFnv,
            "signature ledger identity changed");
    return signatures;
}

std::vector<Pair637> read_current_residual637(
    const std::filesystem::path& path) {
    std::ifstream input(path);
    require(static_cast<bool>(input), "cannot open current residual");
    std::vector<Pair637> rows;
    FnvLocal ledger;
    std::string line;
    while (std::getline(input, line)) {
        require(!line.empty(), "blank current-residual row");
        const std::vector<std::string> fields = split637(line, ',');
        require(fields.size() == 2, "malformed current-residual row");
        std::size_t used_q = 0;
        std::size_t used_r = 0;
        const Pair637 pair{std::stoi(fields[0], &used_q),
                           std::stoi(fields[1], &used_r)};
        require(used_q == fields[0].size() && used_r == fields[1].size() &&
                    pair.q > 0 && pair.q < pair.r &&
                    (rows.empty() || rows.back() < pair),
                "invalid/unsorted current-residual row");
        rows.push_back(pair);
        ledger.add(pair.q);
        ledger.add(pair.r);
    }
    require(rows.size() == kCurrentResidualRows &&
                ledger.state == kCurrentResidualFnv,
            "current residual identity changed");
    return rows;
}

std::vector<u32> read_joint637(const std::filesystem::path& path) {
    std::ifstream input(path);
    require(static_cast<bool>(input), "cannot open joint deck");
    std::vector<u32> deck;
    std::set<u32> distinct;
    FnvLocal ledger;
    std::string token;
    while (input >> token) {
        std::size_t used = 0;
        const u64 wide = std::stoull(token, &used, 16);
        require(used == token.size() && wide < (UINT64_C(1) << 30),
                "invalid joint mask token");
        const u32 mask = static_cast<u32>(wide);
        require(std::popcount(mask) == 8 && distinct.insert(mask).second,
                "joint mask rank/distinctness changed");
        deck.push_back(mask);
        ledger.add(mask);
    }
    require(deck.size() == kJointRows && ledger.state == kJointFnv,
            "joint deck identity changed");
    for (std::size_t local = 0; local < kDeletedIndices.size(); ++local)
        require(deck[kDeletedIndices[local]] == kDeletedMasks[local],
                "deleted joint mask changed");
    return deck;
}

u32 next_same_popcount637(u32 value) {
    const u32 low = value & (0u - value);
    const u32 ripple = value + low;
    return ripple | (((value ^ ripple) >> 2) / low);
}

std::vector<LostBody637> enumerate_lost_bodies637(
    const std::vector<u32>& deck, u64& retained_checks,
    u64& body_fnv, u64& body_response_fnv) {
    std::array<bool, kJointRows> deleted{};
    for (std::size_t index : kDeletedIndices) deleted[index] = true;
    std::vector<LostBody637> lost;
    std::array<u64, 4> response_histogram{};
    FnvLocal body_ledger;
    FnvLocal body_response_ledger;
    u32 body = (u32{1} << 9) - 1;
    for (std::size_t ordinal = 0; ordinal < kBodyRows; ++ordinal) {
        bool retained_hit = false;
        for (std::size_t index = 0; index < deck.size(); ++index) {
            if (deleted[index]) continue;
            ++retained_checks;
            if ((body & deck[index]) == 0) {
                retained_hit = true;
                break;
            }
        }
        if (!retained_hit) {
            unsigned response = 0;
            for (unsigned local = 0; local < kDeletedIndices.size(); ++local)
                if ((body & deck[kDeletedIndices[local]]) == 0)
                    response |= 1u << local;
            require(response != 0, "original joint deck failed body cover");
            lost.push_back({body, response});
            ++response_histogram[response];
            body_ledger.add(body);
            body_response_ledger.add(body);
            body_response_ledger.add(response);
        }
        if (ordinal + 1 < kBodyRows) body = next_same_popcount637(body);
    }
    require(body == UINT32_C(0x3fe00000), "body endpoint changed");
    body_fnv = body_ledger.state;
    body_response_fnv = body_response_ledger.state;
    require(retained_checks == kRetainedChecks &&
                lost.size() == kExpectedBodies.size() &&
                response_histogram[1] == 4 && response_histogram[2] == 2 &&
                response_histogram[3] == 0 && body_fnv == kBodyFnv &&
                body_response_fnv == kBodyResponseFnv,
            "two-deletion obligation census changed");
    for (std::size_t index = 0; index < lost.size(); ++index)
        require(lost[index].body == kExpectedBodies[index] &&
                    lost[index].deleted_response ==
                        kExpectedDeletedResponses[index],
                "ordered lost-body ledger changed");
    return lost;
}

i128 direct_mass637(const AtomData& atoms, u32 mask) {
    i128 mass = 0;
    for (const auto& [atom, value] : atoms.mass)
        if ((atom & ~mask) == 0) mass += value;
    return mass;
}

void add_i128_ledger637(FnvLocal& ledger, i128 value) {
    require(value >= 0, "negative value passed to unsigned margin ledger");
    const __uint128_t wide = static_cast<__uint128_t>(value);
    ledger.add(static_cast<u64>(wide));
    ledger.add(static_cast<u64>(wide >> 64));
}

std::vector<u32> build_rebuilt_deck637(const std::vector<u32>& joint) {
    std::vector<u32> rebuilt;
    rebuilt.reserve(kJointRows);
    for (std::size_t index = 0; index < joint.size(); ++index)
        if (index != kDeletedIndices[0] && index != kDeletedIndices[1])
            rebuilt.push_back(joint[index]);
    rebuilt.insert(rebuilt.end(), kWitnessMasks.begin(), kWitnessMasks.end());
    std::set<u32> distinct(rebuilt.begin(), rebuilt.end());
    FnvLocal ledger;
    for (u32 mask : rebuilt) {
        require(std::popcount(mask) == 8, "rebuilt mask rank changed");
        ledger.add(mask);
    }
    require(rebuilt.size() == kJointRows && distinct.size() == kJointRows &&
                ledger.state == kRebuiltDeckFnv,
            "rebuilt deck identity/distinctness changed");
    return rebuilt;
}

struct BodyRescan637 {
    u64 checks = 0;
    u64 maximum_prefix = 0;
    u64 failures = 0;
    u64 row_fnv = 0;
};

BodyRescan637 rescan_rebuilt_body_cover637(const std::vector<u32>& deck) {
    BodyRescan637 audit;
    FnvLocal ledger;
    u32 body = (u32{1} << 9) - 1;
    for (std::size_t ordinal = 0; ordinal < kBodyRows; ++ordinal) {
        u64 prefix = 0;
        bool hit = false;
        for (u32 mask : deck) {
            ++prefix;
            ++audit.checks;
            if ((body & mask) == 0) {
                hit = true;
                break;
            }
        }
        if (!hit) {
            ++audit.failures;
            prefix = 0;
        } else {
            audit.maximum_prefix = std::max(audit.maximum_prefix, prefix);
        }
        ledger.add(body);
        ledger.add(prefix);
        if (ordinal + 1 < kBodyRows) body = next_same_popcount637(body);
    }
    require(body == UINT32_C(0x3fe00000),
            "rebuilt body endpoint changed");
    audit.row_fnv = ledger.state;
    require(audit.failures == 0, "rebuilt deck failed body cover");
    return audit;
}

u64 pair_fnv637(const std::vector<Pair637>& rows) {
    FnvLocal ledger;
    for (const Pair637 pair : rows) {
        ledger.add(pair.q);
        ledger.add(pair.r);
    }
    return ledger.state;
}

}  // namespace

int main(int argc, char** argv) {
    try {
        std::cout.setf(std::ios::unitbuf);
        require(argc == 6,
                "usage: signature275-345-surgery JOINT421 SIGNATURES24223 "
                "CURRENT22682 FIBRE_OUT WITNESS_OUT");
        init_choose8_local();

        const std::vector<u32> joint = read_joint637(argv[1]);
        const std::map<Pair637, Signature637> signatures =
            read_signatures637(argv[2]);
        const std::vector<Pair637> current = read_current_residual637(argv[3]);
        const Pair637 target_pair{520, 637};
        const auto target_found = signatures.find(target_pair);
        require(target_found != signatures.end(), "target signature missing");
        const Signature637& target_signature = target_found->second;
        require(target_signature.weight == 2 &&
                    signature_indices637(target_signature) ==
                        std::vector<std::size_t>(kDeletedIndices.begin(),
                                                 kDeletedIndices.end()),
                "target inactive signature changed");

        std::vector<Pair637> fibre;
        std::array<u64, 3> signature_shape_counts{};
        for (const Pair637 pair : current) {
            const auto found = signatures.find(pair);
            require(found != signatures.end(),
                    "current row absent from signature universe");
            if (!signature_subset637(found->second, target_signature)) continue;
            fibre.push_back(pair);
            const std::vector<std::size_t> indices =
                signature_indices637(found->second);
            if (indices == std::vector<std::size_t>{275})
                ++signature_shape_counts[0];
            else if (indices == std::vector<std::size_t>{345})
                ++signature_shape_counts[1];
            else if (indices == std::vector<std::size_t>{275, 345})
                ++signature_shape_counts[2];
            else
                require(false, "unexpected signature inside target ideal");
        }
        require(fibre.size() == kFibreRows && pair_fnv637(fibre) == kFibreFnv &&
                    signature_shape_counts == std::array<u64, 3>{14, 16, 3} &&
                    std::find(fibre.begin(), fibre.end(), target_pair) !=
                        fibre.end(),
                "current target-signature ideal changed");

        u64 retained_checks = 0;
        u64 body_fnv = 0;
        u64 body_response_fnv = 0;
        const std::vector<LostBody637> lost = enumerate_lost_bodies637(
            joint, retained_checks, body_fnv, body_response_fnv);

        const std::vector<u32> rebuilt = build_rebuilt_deck637(joint);
        const std::vector<Cell> cells = build_pool_cells();
        require(cells.size() == 7133, "pool-cell count changed");
        std::vector<unsigned char> common_active(EXPECTED_REPAIRS, 1);
        u64 complete_activity_tests = 0;
        u64 direct_activity_tests = 0;
        u64 equalities = 0;
        FnvLocal activity_ledger;
        i128 weakest_margin = std::numeric_limits<i128>::max();
        Pair637 weakest_pair;
        u32 weakest_mask = 0;

        for (const Pair637 pair : fibre) {
            const ActiveUniverse active =
                build_active_universe(cells, pair.q, pair.r);
            for (u64 rank = 0; rank < EXPECTED_REPAIRS; ++rank)
                common_active[rank] &= active.active[rank];
            const Signature637& signature = signatures.at(pair);
            for (std::size_t index = 0; index < joint.size(); ++index) {
                const bool inactive =
                    active.active[colex_rank8_local(joint[index])] == 0;
                require(inactive == signature_bit637(signature, index),
                        "signature/full-activity disagreement");
                ++complete_activity_tests;
            }

            const i64 g = std::gcd(pair.q, pair.r);
            const PrimitivePair primitive =
                build_primitive(pair.q / g, pair.r / g);
            const AtomData atoms = build_cocycle_atoms(cells, primitive, g);
            const i128 denominator =
                static_cast<i128>(primitive.grid) * g * COMMON;
            for (u32 mask : rebuilt) {
                const i128 margin =
                    static_cast<i128>(63) * direct_mass637(atoms, mask) -
                    static_cast<i128>(4) * denominator;
                const bool active_direct = margin >= 0;
                require(active_direct == static_cast<bool>(
                            active.active[colex_rank8_local(mask)]),
                        "direct/full activity disagreement");
                require(active_direct, "rebuilt deck inactive on fibre row");
                equalities += margin == 0;
                if (margin < weakest_margin) {
                    weakest_margin = margin;
                    weakest_pair = pair;
                    weakest_mask = mask;
                }
                activity_ledger.add(pair.q);
                activity_ledger.add(pair.r);
                activity_ledger.add(mask);
                add_i128_ledger637(activity_ledger, margin);
                ++direct_activity_tests;
            }
        }
        require(complete_activity_tests == kFibreRows * kJointRows &&
                    direct_activity_tests == kFibreRows * kJointRows &&
                    equalities == 0 &&
                    activity_ledger.state == kActivityLedgerFnv &&
                    weakest_pair == Pair637{103, 205} &&
                    weakest_mask == kWitnessMasks[1] &&
                    weakest_margin == kWeakestMargin,
                "fibre activity test count/equality changed");

        FnvLocal common_active_ledger;
        FnvLocal common_response_ledger;
        u64 common_active_count = 0;
        u64 response_incidences = 0;
        unsigned response_union = 0;
        std::map<unsigned, ResponseClass637> classes;
        for (u64 rank = 0; rank < EXPECTED_REPAIRS; ++rank) {
            if (!common_active[rank]) continue;
            const u32 mask = unrank_colex8(rank);
            ++common_active_count;
            common_active_ledger.add(mask);
            unsigned response = 0;
            for (unsigned index = 0; index < lost.size(); ++index)
                if ((mask & lost[index].body) == 0)
                    response |= 1u << index;
            response_union |= response;
            response_incidences += std::popcount(response);
            common_response_ledger.add(mask);
            common_response_ledger.add(response);
            ResponseClass637& response_class = classes[response];
            ++response_class.count;
            if (response_class.count == 1 || mask < response_class.least)
                response_class.least = mask;
        }
        require(common_active_count == kCommonActiveCount &&
                    common_active_ledger.state == kCommonActiveFnv &&
                    common_response_ledger.state == kCommonResponseFnv &&
                    response_union == 0x3f && response_incidences == 135082 &&
                    classes.size() == kExpectedClasses.size(),
                "common-active response quotient changed");
        FnvLocal class_ledger;
        std::size_t expected_class_index = 0;
        for (const auto& [pattern, response_class] : classes) {
            const FrozenClass637 expected =
                kExpectedClasses[expected_class_index++];
            require(pattern == expected.pattern &&
                        response_class.count == expected.count &&
                        response_class.least == expected.least,
                    "ordered response class changed");
            class_ledger.add(pattern);
            class_ledger.add(response_class.count);
            class_ledger.add(response_class.least);
        }
        require(class_ledger.state == kClassFnv && !classes.contains(0x3f),
                "response-class ledger/full-responder boundary changed");

        std::array<int, 64> distance;
        std::array<unsigned, 64> predecessor{};
        std::array<unsigned, 64> used_pattern{};
        distance.fill(-1);
        std::queue<unsigned> queue;
        distance[0] = 0;
        queue.push(0);
        while (!queue.empty()) {
            const unsigned covered = queue.front();
            queue.pop();
            for (const auto& [pattern, response_class] : classes) {
                (void)response_class;
                if (pattern == 0) continue;
                const unsigned joined = covered | pattern;
                if (distance[joined] >= 0) continue;
                distance[joined] = distance[covered] + 1;
                predecessor[joined] = covered;
                used_pattern[joined] = pattern;
                queue.push(joined);
            }
        }
        require(distance[0x3f] == 2 && classes.at(0x24).least ==
                    kWitnessMasks[0] && classes.at(0x1b).least ==
                    kWitnessMasks[1] && (0x24 | 0x1b) == 0x3f,
                "exact minimum-two witness changed");
        FnvLocal witness_ledger;
        for (u32 mask : kWitnessMasks) witness_ledger.add(mask);
        require(witness_ledger.state == kWitnessFnv,
                "witness ledger identity changed");

        const BodyRescan637 body_rescan =
            rescan_rebuilt_body_cover637(rebuilt);
        require(body_rescan.checks == kRebuiltBodyChecks &&
                    body_rescan.maximum_prefix == kJointRows &&
                    body_rescan.failures == 0 &&
                    body_rescan.row_fnv == kRebuiltBodyRowFnv,
                "rebuilt body-rescan ledger changed");

        std::ofstream fibre_output(argv[4]);
        std::ofstream witness_output(argv[5]);
        require(static_cast<bool>(fibre_output) &&
                    static_cast<bool>(witness_output),
                "cannot create output ledgers");
        for (const Pair637 pair : fibre)
            fibre_output << pair.q << ',' << pair.r << '\n';
        for (u32 mask : kWitnessMasks)
            witness_output << std::hex << std::setw(8) << std::setfill('0')
                           << mask << std::dec << std::setfill(' ') << '\n';
        require(fibre_output.good() && witness_output.good(),
                "output ledger write failed");

        std::cout << "THM4287_SIGNATURE275_345_FIBRE_SURGERY_V1\n"
                  << "SIGNATURE_ROWS " << signatures.size()
                  << " PAIR_FNV " << std::hex << kSignaturePairFnv
                  << " CONTENT_FNV " << kSignatureContentFnv << std::dec
                  << " CURRENT_RESIDUAL " << current.size() << " FNV "
                  << std::hex << kCurrentResidualFnv << std::dec << '\n'
                  << "TARGET 520,637 SIGNATURE 275,345 DELETED_MASKS "
                  << std::hex << std::setw(8) << std::setfill('0')
                  << kDeletedMasks[0] << ' ' << std::setw(8)
                  << kDeletedMasks[1] << std::dec << std::setfill(' ')
                  << "\nFIBRE ROWS " << fibre.size() << " FNV " << std::hex
                  << pair_fnv637(fibre) << std::dec
                  << " SIGNATURE_COUNTS 275:14 345:16 275+345:3\n"
                  << "LOST_BODIES " << lost.size() << " BODY_FNV "
                  << std::hex << body_fnv << " BODY_RESPONSE_FNV "
                  << body_response_fnv << std::dec << " RETAINED_CHECKS "
                  << retained_checks << '\n';
        for (std::size_t index = 0; index < lost.size(); ++index)
            std::cout << "OBLIGATION " << index << " BODY " << std::hex
                      << std::setw(8) << std::setfill('0') << lost[index].body
                      << std::dec << std::setfill(' ') << " DELETED_RESPONSE "
                      << lost[index].deleted_response << '\n';
        std::cout << "COMMON_ACTIVE " << common_active_count << " FNV "
                  << std::hex << common_active_ledger.state
                  << " RESPONSE_FNV " << common_response_ledger.state
                  << " CLASS_FNV " << class_ledger.state << std::dec
                  << " CLASSES " << classes.size()
                  << " RESPONSE_INCIDENCES " << response_incidences << '\n';
        for (const auto& [pattern, response_class] : classes)
            std::cout << "CLASS " << std::hex << pattern << " LEAST "
                      << std::setw(8) << std::setfill('0')
                      << response_class.least << std::dec << std::setfill(' ')
                      << " COVER " << std::popcount(pattern) << " COUNT "
                      << response_class.count << '\n';
        std::cout << "EXACT_MINIMUM 2 NO_FULL_RESPONDER 1 WITNESS "
                  << std::hex << std::setw(8) << std::setfill('0')
                  << kWitnessMasks[0] << ' ' << std::setw(8)
                  << kWitnessMasks[1] << " WITNESS_FNV " << kWitnessFnv
                  << std::dec << std::setfill(' ') << '\n'
                  << "REBUILT_DECK " << rebuilt.size() << " FNV " << std::hex
                  << kRebuiltDeckFnv << std::dec << " BODY_SCAN "
                  << kBodyRows << " CHECKS " << body_rescan.checks
                  << " MAX_PREFIX " << body_rescan.maximum_prefix
                  << " FAILURES " << body_rescan.failures << " ROW_FNV "
                  << std::hex << body_rescan.row_fnv << std::dec << '\n'
                  << "ACTIVITY COMPLETE_TESTS " << complete_activity_tests
                  << " DIRECT_TESTS " << direct_activity_tests
                  << " EQUALITIES " << equalities << " LEDGER_FNV "
                  << std::hex << activity_ledger.state << std::dec
                  << " WEAKEST_PAIR " << weakest_pair.q << ','
                  << weakest_pair.r << " WEAKEST_MASK " << std::hex
                  << std::setw(8) << std::setfill('0') << weakest_mask
                  << std::dec << std::setfill(' ') << " WEAKEST_MARGIN_NUM "
                  << decimal(weakest_margin) << '\n'
                  << "VERDICT PASS EXACT_33_ROW_COMMON_DECK_SURGERY\n"
                  << "SCOPE FIXED_POOL_FINITE_EXACT NO_PHYSICAL_ENTRY_NO_LRC14\n";
        return 0;
    } catch (const std::exception& error) {
        std::cerr << "THM4287_SIGNATURE_SURGERY_ERROR " << error.what()
                  << '\n';
        return 1;
    }
}
